                                            }

                                            used[r] = 0;
                                        }
                                    }

                                    used[l] = 0;
                                }
                            }

                            used[b] = 0;
                        }
                    }

                    used[f] = 0;
                }
            }
        }
    }

    if (sols.sz == 0) {
        printf("0\n");
        return 0;
    }

    qsort(sols.a, sols.sz, sizeof(CubeState), cmpStateQ);

    long long ans = 1;
    for (int i = 1; i < sols.sz; i++) {
        if (cmpState(&sols.a[i-1], &sols.a[i]) != 0) ans++;
    }

    printf("%lld\n", ans);
    return 0;
