    }

    // All 24 rotations of a cube mapping face indices
    static final int[][] rotations = {
        {0,1,2,3,4,5},
        {0,2,3,1,4,5},
        {0,3,1,2,4,5},
        {1,0,4,5,2,3},
        {1,4,5,0,2,3},
        {1,5,0,4,2,3},
        {2,0,5,4,3,1},
        {2,5,4,0,3,1},
        {2,4,0,5,3,1},
        {3,0,1,5,4,2},
