        {2,4,3,1,0,5},
        {2,3,1,4,0,5}
    };

    static int countCubes(int[] tiles) {
        // Try all assignments of tiles to faces (6! = 720)
        int[] perm = new int[6];
        boolean[] used = new boolean[6];
        int[] count = new int[1];
        enumerateAssignments(tiles, perm, used, 0, count);
        return count[0];
    }

    static void enumerateAssignments(int[] tiles, int[] perm, boolean[] used, int idx, int[] count) {
        if (idx == 6) {
            if (validCube(tiles, perm)) {
                String key = canonicalForm(tiles, perm);
                if (!seen.contains(key)) {
                    seen.add(key);
                    count[0]++;
                }
            }
            return;
        }
        for (int i = 0; i < 6; i++) {
            if (!used[i]) {
                used[i] = true;
                perm[idx] = i;
                enumerateAssignments(tiles, perm, used, idx + 1, count);
                used[i] = false;
            }
        }
    }

    // Check if cube with given tile assignment and tile rotations is valid
    static boolean validCube(int[] tiles, int[] assign) {
        // assign[face] = tile index in tiles array
        // Try all 4 rotations of each tile (0..3)
        for (int r0 = 0; r0 < 4; r0++) {
            for (int r1 = 0; r1 < 4; r1++) {
                for (int r2 = 0; r2 < 4; r2++) {
                    for (int r3 = 0; r3 < 4; r3++) {
                        for (int r4 = 0; r4 < 4; r4++) {
                            for (int r5 = 0; r5 < 4; r5++) {
                                int[] rotations = {r0, r1, r2, r3, r4, r5};
                                if (checkCube(tiles, assign, rotations)) {
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    // Check vertex color consistency given tile assignments and rotations
    static boolean checkCube(int[] tiles, int[] assign, int[] rot) {
        int[][] faceColors = new int[6][4];
        for (int f = 0; f < 6; f++) {
            int tileIdx = tiles[assign[f]];
            int r = rot[f];
            for (int c = 0; c < 4; c++) {
                faceColors[f][c] = colors[tileIdx][(c + r) % 4];
            }
        }
        // 8 vertices of cube, each vertex meets 3 faces
        // Vertex mapping: face corners (0..3) and adjacency
        int[][] vertFaces = {
            {0,1,2}, // vertex 0: faces 0,1,2 meet
            {0,1,3},
            {0,2,4},
            {0,3,4},
            {1,2,5},
            {1,3,5},
            {2,4,5},
            {3,4,5}
        };
        // corner index on each face for each vertex
        int[][] vertCorners = {
            {0,0,0},
            {1,1,0},
            {3,3,1},
            {2,2,1},
            {1,2,2},
            {0,3,2},
            {2,0,3},
            {3,1,3}
        };
        for (int v = 0; v < 8; v++) {
            int c0 = faceColors[vertFaces[v][0]][vertCorners[v][0]];
            int c1 = faceColors[vertFaces[v][1]][vertCorners[v][1]];
            int c2 = faceColors[vertFaces[v][2]][vertCorners[v][2]];
            if (c0 != c1 || c1 != c2) return false;
        }
        return true;
    }

    // Generate canonical key for cube to avoid rotation duplicates
    static String canonicalForm(int[] tiles, int[] assign) {
        // Represent cube as sorted list of face representations
        // Each face: tile number + rotation
        // We'll generate all rotations and pick lexicographically smallest
        List<String> candidates = new ArrayList<>();
        for (int[] rot : rotations) {
            StringBuilder sb = new StringBuilder();
            for (int f = 0; f < 6; f++) {
                int originalFace = rot[f];
                int tileIdx = tiles[assign[originalFace]];
                // We don't store rotation here because we already fixed orientation
                sb.append(tileIdx).append(",");
            }
            candidates.add(sb.toString());
        }
        Collections.sort(candidates);
        return candidates.get(0);
    }
}

