/*
 *  AtCoder-like problem:
 *  Count distinct cubes made from given square tiles.
 *
 *  Idea:
 *  - A cube has 6 faces. Each face uses one tile, with one of 4 rotations.
 *  - For every cube vertex, the 3 touching tile corners must have equal color.
 *  - Two completed cubes are identical if they differ only by a 3D rotation.
 *
 *  We count all valid labeled/oriented constructions, then quotient by 24
 *  because every finished cube has no nontrivial stabilizer under face-number labels
 *  (tile numbers are distinct and face set/orientation is fixed), so each unlabeled
 *  cube corresponds to exactly 24 global rotations.
 *
 *  Construction strategy:
 *  - Fix one tile as the "top" face and one of its 4 rotations.
 *  - Determine possible side faces by matching edge corner colors with the top.
 *  - Build the 4 side faces cyclically, enforcing edge/vertex consistency.
 *  - The bottom face is then forced by the lower edges of the 4 side faces.
 *  - Use bitmasks to ensure distinct tiles.
 *
 *  Representation:
 *  For a face rotation r, corners become:
 *      a[0] = C[(0-r)&3], a[1] = C[(1-r)&3], a[2] = C[(2-r)&3], a[3] = C[(3-r)&3]
 *  i.e. rotating clockwise by r.
 *
 *  Cube net convention:
 *      top T
 *      sides S0,S1,S2,S3 around it
 *      bottom B
 *
 *  For side Sk:
 *      top edge    = (corner 0,1)
 *      right edge  = (1,2)
 *      bottom edge = (2,3)
 *      left edge   = (3,0)
 *
 *  Adjacent constraints:
 *      T edge k must equal Sk top edge
 *      Sk right edge matches S(k+1) left edge
 *      Bottom top? We use the 4 side bottom edges to determine B's 4 edges.
 *
 *  Vertex equalities are naturally enforced by edge endpoint equalities in this setup.
 *
 *  N is small enough for O(N^3 * constant) style with precomputed edge matches.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static int[][] C;          // original colors
    static int[][][] R;        // rotated corners [tile][rot][4]

    // For each ordered color pair (x,y), list of (tile,rot) whose top edge is (x,y)
    static long[][] pairList;
    static final int MAXC = 1000;

    static long encode(int tile, int rot) {
        return (((long) tile) << 2) | rot;
    }

    static int decTile(long v) {
        return (int) (v >> 2);
    }

    static int decRot(long v) {
        return (int) (v & 3);
    }

    static int[] getRot(int tile, int rot) {
        return R[tile][rot];
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        C = new int[N][4];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < 4; j++) C[i][j] = fs.nextInt();
        }

        R = new int[N][4][4];
        for (int i = 0; i < N; i++) {
            for (int r = 0; r < 4; r++) {
                for (int k = 0; k < 4; k++) {
                    R[i][r][k] = C[i][(k - r + 4) & 3];
                }
            }
        }

        int pairCount = (MAXC + 1) * (MAXC + 1);
        pairList = new long[pairCount][];
        ArrayList<Long>[] tmp = new ArrayList[pairCount];
        for (int i = 0; i < pairCount; i++) tmp[i] = null;

        for (int i = 0; i < N; i++) {
            for (int r = 0; r < 4; r++) {
                int a = R[i][r][0];
                int b = R[i][r][1];
                int key = a * (MAXC + 1) + b;
                if (tmp[key] == null) tmp[key] = new ArrayList<>();
                tmp[key].add(encode(i, r));
            }
        }
        for (int i = 0; i < pairCount; i++) {
            if (tmp[i] == null) pairList[i] = new long[0];
            else {
                ArrayList<Long> al = tmp[i];
                long[] arr = new long[al.size()];
                for (int j = 0; j < al.size(); j++) arr[j] = al.get(j);
                pairList[i] = arr;
            }
        }

        long total = 0;

        // Choose top face tile and rotation.
        for (int t = 0; t < N; t++) {
            long bitT = 1L << t;
            for (int rt = 0; rt < 4; rt++) {
                int[] top = R[t][rt];

                // Side S0 must have top edge = (top[0], top[1])
                long[] cand0 = pairList[top[0] * (MAXC + 1) + top[1]];
                for (long e0 : cand0) {
                    int s0 = decTile(e0), r0 = decRot(e0);
                    if ((bitT & (1L << s0)) != 0) continue;
                    int[] A0 = R[s0][r0];
                    long bit0 = bitT | (1L << s0);

                    // S1 top edge = (top[1], top[2]) and left edge = S0 right edge
                    int need10 = top[1], need11 = top[2];
                    int left1a = A0[1], left1b = A0[2]; // S0 right edge must match S1 left edge => S1[3,0] = [A0[1],A0[2]]
                    long[] cand1 = pairList[need10 * (MAXC + 1) + need11];
                    for (long e1 : cand1) {
                        int s1 = decTile(e1), r1 = decRot(e1);
                        long b1 = 1L << s1;
                        if ((bit0 & b1) != 0) continue;
                        int[] A1 = R[s1][r1];
                        if (A1[3] != left1a || A1[0] != left1b) continue;
                        long bit1 = bit0 | b1;

                        // S2
                        int need20 = top[2], need21 = top[3];
                        int left2a = A1[1], left2b = A1[2];
                        long[] cand2 = pairList[need20 * (MAXC + 1) + need21];
                        for (long e2 : cand2) {
                            int s2 = decTile(e2), r2 = decRot(e2);
                            long b2 = 1L << s2;
                            if ((bit1 & b2) != 0) continue;
                            int[] A2 = R[s2][r2];
                            if (A2[3] != left2a || A2[0] != left2b) continue;
                            long bit2 = bit1 | b2;

                            // S3
                            int need30 = top[3], need31 = top[0];
                            int left3a = A2[1], left3b = A2[2];
                            long[] cand3 = pairList[need30 * (MAXC + 1) + need31];
                            for (long e3 : cand3) {
                                int s3 = decTile(e3), r3 = decRot(e3);
                                long b3 = 1L << s3;
                                if ((bit2 & b3) != 0) continue;
                                int[] A3 = R[s3][r3];
                                if (A3[3] != left3a || A3[0] != left3b) continue;

                                // Close the ring: S3 right edge matches S0 left edge
                                if (A3[1] != A0[3] || A3[2] != A0[0]) continue;

                                long bit3 = bit2 | b3;

                                // Bottom face B:
                                // Its edges around must match side bottom edges:
                                // B top edge    = reversed S2 bottom? Instead of geometric derivation by edges,
                                // use vertex consistency:
                                //
                                // Bottom corners (b0,b1,b2,b3) are forced by lower vertices:
                                // between S0,S1 -> A0[2]=A1[3]
                                // between S1,S2 -> A1[2]=A2[3]
                                // between S2,S3 -> A2[2]=A3[3]
                                // between S3,S0 -> A3[2]=A0[3]
                                //
                                // Thus B corners in cyclic order can be:
                                // [A0[3], A0[2], A1[2], A2[2]]
                                // Need consistency with all four side bottom edges:
                                // B edge 0-1 = S0 bottom reversed? This gives exact rotated-corner check.
                                int[] needB = new int[] {A0[3], A0[2], A1[2], A2[2]};
                                if (needB[0] != A3[2]) continue; // from S3-S0 lower shared vertex
                                if (needB[3] != A3[3]) continue; // from S2-S3 lower shared vertex

                                for (int b = 0; b < N; b++) {
                                    if ((bit3 & (1L << b)) != 0) continue;
                                    for (int rb = 0; rb < 4; rb++) {
                                        int[] B = R[b][rb];
                                        if (B[0] == needB[0] && B[1] == needB[1] && B[2] == needB[2] && B[3] == needB[3]) {
                                            total++;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Each actual cube counted once for each global rotation = 24 times.
        System.out.println(total / 24);
    }
}

