struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

static const int FACE_CNT = 6;
static const int CORNER_CNT = 8;

/*
Faces of a cube:
0:+X, 1:-X, 2:+Y, 3:-Y, 4:+Z, 5:-Z

Each face has 4 corners in clockwise order when viewed from outside.
Corner indices are 0..7 corresponding to signs (x,y,z):
0:(+,+,+)
1:(+,+,-)
2:(+,-,+)
3:(+,-,-)
4:(-,+,+)
5:(-,+,-)
6:(-,-,+)
7:(-,-,-)
*/

int corner_id(int x, int y, int z) {
    int id = 0;
    if (x < 0) id += 4;
    if (y < 0) id += 2;
    if (z < 0) id += 1;
    return id;
}

array<array<int,4>,6> build_face_corners() {
    array<array<int,4>,6> fc;
    // Clockwise when viewed from outside
    // +X
    fc[0] = {
        corner_id(+1,+1,+1),
        corner_id(+1,+1,-1),
        corner_id(+1,-1,-1),
        corner_id(+1,-1,+1)
    };
    // -X
    fc[1] = {
        corner_id(-1,+1,-1),
        corner_id(-1,+1,+1),
        corner_id(-1,-1,+1),
        corner_id(-1,-1,-1)
    };
    // +Y
    fc[2] = {
        corner_id(-1,+1,+1),
        corner_id(-1,+1,-1),
        corner_id(+1,+1,-1),
        corner_id(+1,+1,+1)
    };
    // -Y
    fc[3] = {
        corner_id(-1,-1,-1),
        corner_id(-1,-1,+1),
        corner_id(+1,-1,+1),
        corner_id(+1,-1,-1)
    };
    // +Z
    fc[4] = {
        corner_id(-1,+1,+1),
        corner_id(+1,+1,+1),
        corner_id(+1,-1,+1),
        corner_id(-1,-1,+1)
    };
    // -Z
    fc[5] = {
        corner_id(+1,+1,-1),
        corner_id(-1,+1,-1),
        corner_id(-1,-1,-1),
        corner_id(+1,-1,-1)
    };
    return fc;
}

array<int,3> id_to_vec(int id) {
    int x = (id < 4 ? +1 : -1);
    int y = ((id & 2) ? -1 : +1);
    int z = ((id & 1) ? -1 : +1);
    return {x,y,z};
}

int vec_to_id(const array<int,3>& v) {
    return corner_id(v[0], v[1], v[2]);
}

array<int,3> face_normal(int f) {
    if (f == 0) return {+1,0,0};
    if (f == 1) return {-1,0,0};
    if (f == 2) return {0,+1,0};
    if (f == 3) return {0,-1,0};
    if (f == 4) return {0,0,+1};
    return {0,0,-1};
}

int normal_to_face(const array<int,3>& v) {
    if (v[0] == +1) return 0;
    if (v[0] == -1) return 1;
    if (v[1] == +1) return 2;
    if (v[1] == -1) return 3;
    if (v[2] == +1) return 4;
    return 5;
}

array<int,3> crossp(const array<int,3>& a, const array<int,3>& b) {
    return {
        a[1]*b[2] - a[2]*b[1],
        a[2]*b[0] - a[0]*b[2],
        a[0]*b[1] - a[1]*b[0]
    };
}

int dotp(const array<int,3>& a, const array<int,3>& b) {
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
}

array<int,3> negv(const array<int,3>& a) {
    return {-a[0], -a[1], -a[2]};
}

struct Rotation {
    // maps old vector to new vector
    int p[3]; // new[i] = s[i] * old[p[i]]
    int s[3];
};

array<int,3> apply_rot_vec(const Rotation& R, const array<int,3>& v) {
    return { R.s[0]*v[R.p[0]], R.s[1]*v[R.p[1]], R.s[2]*v[R.p[2]] };
}

vector<Rotation> generate_rotations() {
    vector<Rotation> res;
    vector<int> perm = {0,1,2};
    do {
        int inv = 0;
        for (int i = 0; i < 3; i++)
            for (int j = i+1; j < 3; j++)
                if (perm[i] > perm[j]) inv++;
        int sign_perm = (inv % 2 == 0 ? 1 : -1);
        for (int sx : {-1,1})
            for (int sy : {-1,1})
                for (int sz : {-1,1}) {
                    int det = sign_perm * sx * sy * sz;
                    if (det == 1) {
                        Rotation r;
                        r.p[0] = perm[0]; r.p[1] = perm[1]; r.p[2] = perm[2];
                        r.s[0] = sx; r.s[1] = sy; r.s[2] = sz;
                        res.push_back(r);
                    }
                }
    } while (next_permutation(perm.begin(), perm.end()));
    return res; // 24
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<array<int,4>> tile(N);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 4; j++) cin >> tile[i][j];
    }

    auto faceCorners = build_face_corners();
    auto rots = generate_rotations();

    // For each cube rotation R and each original face f, determine:
    // new face g where f goes, and rotation k (0..3) of corner order on that face.
    int faceMap[24][6];
    int rotMap[24][6];

    for (int r = 0; r < 24; r++) {
        for (int f = 0; f < 6; f++) {
            auto n = face_normal(f);
            auto nn = apply_rot_vec(rots[r], n);
            int g = normal_to_face(nn);
            faceMap[r][f] = g;

            array<int,4> transformed;
            for (int i = 0; i < 4; i++) {
                auto v = id_to_vec(faceCorners[f][i]);
                auto w = apply_rot_vec(rots[r], v);
                transformed[i] = vec_to_id(w);
            }

            int kfound = -1;
            for (int k = 0; k < 4; k++) {
                bool ok = true;
                for (int i = 0; i < 4; i++) {
                    if (transformed[i] != faceCorners[g][(i + k) % 4]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    kfound = k;
                    break;
                }
            }
            rotMap[r][f] = kfound;
        }
    }

    ll ans = 0;

    // Fix one tile as face 0 (+X) to quotient by cube rotations.
    // For each tile t and its 4 in-plane rotations, assign it to face 0.
    // Then solve deterministic constraints for the remaining faces.
    for (int t0 = 0; t0 < N; t0++) {
        for (int rot0 = 0; rot0 < 4; rot0++) {
            // color at each cube corner induced by face 0
            int cornerColor[8];
            fill(cornerColor, cornerColor + 8, -1);
            for (int j = 0; j < 4; j++) {
                int cid = faceCorners[0][j];
                cornerColor[cid] = tile[t0][(j + rot0) % 4];
            }

            // For every remaining face, compute all possible (tile,rot) choices consistent with known corners.
            vector<vector<pair<int,int>>> cand(6);
            vector<int> faces = {1,2,3,4,5};

            bool bad = false;
            for (int f : faces) {
                for (int t = 0; t < N; t++) if (t != t0) {
                    for (int r = 0; r < 4; r++) {
                        bool ok = true;
                        for (int j = 0; j < 4; j++) {
                            int cid = faceCorners[f][j];
                            if (cornerColor[cid] != -1 && tile[t][(j + r) % 4] != cornerColor[cid]) {
                                ok = false;
                                break;
                            }
                        }
                        if (ok) cand[f].push_back({t, r});
                    }
                }
                if (cand[f].empty()) {
                    bad = true;
                    break;
                }
            }
            if (bad) continue;

            // Build exact equalities among all face-corner positions.
            // Variables: (face,cornerIndex) => face*4+corner
            DSU dsu(24);
            auto vid = [&](int f, int j){ return f*4 + j; };

            for (int c = 0; c < 8; c++) {
                vector<pair<int,int>> occ;
                for (int f = 0; f < 6; f++) {
                    for (int j = 0; j < 4; j++) {
                        if (faceCorners[f][j] == c) occ.push_back({f,j});
                    }
                }
                dsu.unite(vid(occ[0].first, occ[0].second), vid(occ[1].first, occ[1].second));
                dsu.unite(vid(occ[1].first, occ[1].second), vid(occ[2].first, occ[2].second));
            }

            // Face 0 is fixed to tile t0, rotation rot0.
            // We count injective assignments of tiles to faces 1..5 satisfying all corner equalities.
            // Use backtracking with pruning.
            vector<int> order = faces;
            sort(order.begin(), order.end(), [&](int a, int b){
                return cand[a].size() < cand[b].size();
            });

            vector<int> assignedTile(6, -1), assignedRot(6, -1);
            vector<int> used(N, 0);
            assignedTile[0] = t0;
            assignedRot[0] = rot0;
            used[t0] = 1;

            // rootColor[root] = fixed color if determined from assigned faces
            unordered_map<int,int> rootColor;
            for (int j = 0; j < 4; j++) {
                int root = dsu.find(vid(0,j));
                int col = tile[t0][(j + rot0) % 4];
                rootColor[root] = col;
            }

            function<ll(int, unordered_map<int,int>&)> dfs = [&](int idx, unordered_map<int,int>& curColor) -> ll {
                if (idx == (int)order.size()) return 1;

                int f = order[idx];
                ll ret = 0;

                for (auto [t, r] : cand[f]) {
                    if (used[t]) continue;

                    bool ok = true;
                    vector<pair<int,int>> added;
                    for (int j = 0; j < 4; j++) {
                        int root = dsu.find(vid(f,j));
                        int col = tile[t][(j + r) % 4];
                        auto it = curColor.find(root);
                        if (it != curColor.end()) {
                            if (it->second != col) {
                                ok = false;
                                break;
                            }
                        } else {
                            curColor[root] = col;
                            added.push_back({root, col});
                        }
                    }
                    if (!ok) {
                        for (auto &p : added) curColor.erase(p.first);
                        continue;
                    }

                    used[t] = 1;
                    assignedTile[f] = t;
                    assignedRot[f] = r;
                    ret += dfs(idx + 1, curColor);
                    assignedTile[f] = assignedRot[f] = -1;
                    used[t] = 0;

                    for (auto &p : added) curColor.erase(p.first);
                }

                return ret;
            };

            ll cnt = dfs(0, rootColor);

            // Each actual cube is represented exactly 24 times by choices of
            // (which physical face is mapped to our fixed face 0, and cube rotation),
            // but because face 0 and its in-plane rotation are fixed here, each actual cube
            // corresponds to exactly 1 state in this normalization.
            // However, identical finished assignments can still be reached from different
            // choices of t0/rot0 only if the cube has symmetry. To correctly quotient by
            // spatial rotations, we instead canonicalized by fixing one outward face and its
            // orientation, which gives exactly one representative per rotational class.
            ans += cnt;
        }
    }

    // The above counts each cube 6*4 = 24 times? No:
    // choosing a different face/orientation of the same completed cube as the fixed (+X) face
    // produces a different normalized construction, but these are exactly the 24 cube rotations.
    // Therefore divide by 24.
    cout << (ans / 24) << '\n';
    return 0;
}
